import{_ as o,o as t,c as a,a5 as r}from"./chunks/framework.Cct9zD0Q.js";const u=JSON.parse('{"title":"원격 점검이 켜지지 않음","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/manual/troubleshooting/remote-check.md","filePath":"ko/manual/troubleshooting/remote-check.md","lastUpdated":1795599730000}'),l={name:"ko/manual/troubleshooting/remote-check.md"};function d(i,e,c,n,h,m){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="원격-점검이-켜지지-않음" tabindex="-1">원격 점검이 켜지지 않음 <a class="header-anchor" href="#원격-점검이-켜지지-않음" aria-label="Permalink to &quot;원격 점검이 켜지지 않음&quot;">​</a></h1><p><strong>정비</strong> › <code>로봇 점검</code> 맨 아래 <code>원격 점검</code>에서 <code>켜기 1시간</code>이 눌리지 않거나, 눌러도 켜지지 않는 경우입니다. 아래 순서대로 확인하세요. 원격 점검 사용법은 <a href="/RBQ/nightly/ko/manual/gui/maintenance.html#remote-check">정비 › 원격 점검</a>을 보세요.</p><h2 id="connected" tabindex="-1">1. 앱이 로봇에 연결됐는지 확인 <a class="header-anchor" href="#connected" aria-label="Permalink to &quot;1. 앱이 로봇에 연결됐는지 확인 {#connected}&quot;">​</a></h2><p>섹션에 <code>로봇에 연결되어 있지 않습니다</code>가 보이면 앱이 로봇에 붙지 않은 것입니다. 원격 점검은 로봇에서 켜므로 앱이 로봇에 직접 연결되어 있어야 합니다. 로봇 와이파이에 붙어 허브에서 연결하세요(<a href="/RBQ/nightly/ko/manual/gui/connection.html">연결</a> 참고).</p><h2 id="router" tabindex="-1">2. 로봇 공유기가 인터넷에 붙었는지 확인 <a class="header-anchor" href="#router" aria-label="Permalink to &quot;2. 로봇 공유기가 인터넷에 붙었는지 확인 {#router}&quot;">​</a></h2><p>원격 점검은 로봇이 레인보우 서버에 닿아야 켜집니다. 로봇에 USIM이 없으면 로봇 공유기를 현장 와이파이에 붙여야 합니다.</p><ol><li>로봇 와이파이에 붙은 기기의 브라우저에서 <code>http://192.168.0.1</code>을 열고 <code>관리도구</code>로 들어갑니다.</li><li><code>시스템 요약 정보</code>의 <code>인터넷 연결 상태</code>가 <em>인터넷에 정상적으로 연결됨 (무선 WAN)</em> 인지 봅니다.</li><li>아니면 <a href="/RBQ/nightly/ko/manual/operation/robot-internet.html">로봇을 인터넷에 연결하기</a>의 1~3단계를 따라 무선 WAN을 켭니다.</li></ol><p>웹 로그인 화면이 뜨거나 기기(MAC) 등록이 필요한 현장 망에서는 무선 WAN이 인터넷에 닿지 않습니다. 이럴 때는 휴대폰 핫스팟을 현장 와이파이 대신 고르세요.</p><h2 id="dns" tabindex="-1">3. 로봇 DNS 설정 <a class="header-anchor" href="#dns" aria-label="Permalink to &quot;3. 로봇 DNS 설정 {#dns}&quot;">​</a></h2><p>공유기가 인터넷에 붙어도 로봇 PC에 이름 풀이(DNS) 서버가 없으면 레인보우 서버를 찾지 못합니다. 제어권을 가져온 뒤 원격 점검 섹션의 <code>DNS 설정</code>을 누릅니다(<a href="/RBQ/nightly/ko/manual/operation/robot-internet.html#dns">로봇 DNS 설정</a>).</p><ul><li><em>DNS 를 설정했습니다</em> — 다음 단계로 갑니다.</li><li><em>제어권을 가져온 뒤에 누르세요</em> — 제어권을 가져와 다시 누릅니다.</li><li><em>DNS 를 설정하지 못했습니다</em> — 2번(공유기 인터넷)을 다시 확인합니다. 그래도 안 되면 지원 담당에게 문의하세요.</li></ul><p>버튼이 없으면 로봇 소프트웨어가 이 기능보다 오래된 것입니다. <a href="/RBQ/nightly/ko/manual/gui/software-update.html">로봇 소프트웨어를 업데이트</a>하세요.</p><h2 id="register" tabindex="-1">4. 원격 등록이 필요한지 확인 <a class="header-anchor" href="#register" aria-label="Permalink to &quot;4. 원격 등록이 필요한지 확인 {#register}&quot;">​</a></h2><p>섹션에 <code>원격 연결에 필요한 값이 빠져 있습니다</code>가 보이면 로봇이 아직 레인보우 서버에 등록되지 않은 것입니다.</p><ol><li><code>켜기 1시간</code>을 누르면 <code>원격 등록</code> 창이 뜹니다. <code>등록</code>을 누릅니다.</li><li>등록은 앱을 쓰는 기기에서 서버로 요청합니다. <em>인터넷이 필요합니다 — 로봇망에는 인터넷이 없을 수 있습니다. 인터넷 되는 망에서 다시 시도해 주세요</em> 가 나오면 2번을 먼저 끝내세요. 공유기가 인터넷에 붙으면 로봇 와이파이에 붙은 기기도 그 인터넷을 씁니다.</li><li><em>등록됐습니다. 로봇을 다시 시작한 뒤 원격 점검을 다시 켜 주세요.</em> 가 나오면 <code>로봇 서비스 재시작</code>을 누릅니다. 로봇이 앉아 있어야 하고, 제어권을 가진 기기에서만 됩니다.</li><li>로봇이 다시 켜지면 <code>켜기 1시간</code>을 다시 누릅니다.</li></ol><h2 id="errors" tabindex="-1">5. 켜기 오류 문구 <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;5. 켜기 오류 문구 {#errors}&quot;">​</a></h2><p><code>켜기 1시간</code>을 눌렀는데 버튼 아래에 빨간 글씨가 나오는 경우입니다.</p><table tabindex="0"><thead><tr><th>문구</th><th>할 일</th></tr></thead><tbody><tr><td><em>켜지 못했습니다 — 로봇이 인터넷에 연결되어 있지 않습니다</em></td><td>로봇이 레인보우 서버에 붙지 못했습니다. 2번과 3번을 확인합니다. 방금 등록했다면 로봇 서비스를 다시 시작했는지 확인합니다</td></tr><tr><td><em>켜지 못했습니다 — 로봇의 SSH 서버가 꺼져 있습니다</em></td><td>로봇을 껐다가 다시 켭니다. 계속되면 지원 담당에게 문의합니다</td></tr></tbody></table><h2 id="support" tabindex="-1">6. 지원 담당에게 문의할 때 <a class="header-anchor" href="#support" aria-label="Permalink to &quot;6. 지원 담당에게 문의할 때 {#support}&quot;">​</a></h2><p>위를 모두 확인해도 안 되면 아래를 함께 알려 주세요.</p><ul><li>로봇 시리얼 번호(허브 왼쪽 위)</li><li>원격 점검 섹션에 보이는 문구 그대로</li><li>공유기 <code>시스템 요약 정보</code>의 <code>인터넷 연결 상태</code></li></ul>',21)])])}const p=o(l,[["render",d]]);export{u as __pageData,p as default};
